slide4.vulnerable:
function withdraw(bytes[] calldata sigs) external {
  if(sigs.length < 5) {
    revert("quorum");
  }
  release();
}

slide4.corrected:
function withdraw(bytes[] calldata sigs) external {
  if(uniqueTrustedSigners(sigs) < 5) {
    revert("quorum not met");
  }
  if(!withdrawalLimitNotExceeded()) {
    revert("limit exceeded");
  }
  release();
}
